nd prompt-upgrade work."},"path":"C:\\Users\\Admin\\AppData\\Local\\Temp\\16c953ac-55c7-44d8-b2a8-a6b0363e5494\\9b6c8bde-6749-4bdd-99dc-81a7052a69e2\\skills\\.system\\openai-docs\\SKILL.md","scope":"system","enabled":true},{"name":"plugin-creator","description":"Create and scaffold plugin directories for Codex with a required `.codex-plugin/plugin.json`, optional plugin folders/files, valid manifest defaults, and personal-marketplace entries by default. Use when Codex needs to create a new personal plugin, add optional plugin structure, generate or update marketplace entries for plugin ordering and availability metadata, or update an existing local plugin during development with the CLI-driven cachebuster and reinstall flow.","interface":{"displayName":"Plugin Creator","shortDescription":"Scaffold plugins and marketplace entries","iconSmall":"C:\\Users\\Admin\\AppData\\Local\\Temp\\16c953ac-55c7-44d8-b2a8-a6b0363e5494\\9b6c8bde-6749-4bdd-99dc-81a7052a69e2\\skills\\.system\\plugin-creator\\assets\\plugin-creator-small.svg","iconLarge":"C:\\Users\\Admin\\AppData\\Local\\Temp\\16c953ac-55c7-44d8-b2a8-a6b0363e5494\\9b6c8bde-6749-4bdd-99dc-81a7052a69e2\\skills\\.system\\plugin-creator\\assets\\plugin-creator.png","iconSmallUrl":null,"iconLargeUrl":null,"brandColor":null,"defaultPrompt":"Use $plugin-creator to scaffold a valid plugin in the personal marketplace, then validate it before handing it back."},"path":"C:\\Users\\Admin\\AppData\\Local\\Temp\\16c953ac-55c7-44d8-b2a8-a6b0363e5494\\9b6c8bde-6749-4bdd-99dc-81a7052a69e2\\skills\\.system\\plugin-creator\\SKILL.md","scope":"system","enabled":true},{"name":"review-agent","description":"Perform a read-only, defect-first review of a specified code change and return every actionable finding. Use when another agent delegates review of uncommitted changes, a base-branch diff, a commit, or custom review instructions.","interface":{"displayName":"Review Agent","shortDescription":"Find actionable bugs in code changes","iconSmal